<script setup>
import { ref,computed,onMounted } from 'vue'
import AnswerInput from './AnswerInput.vue'
import { useTeaching,copy,dateLabel,statusLabel } from './useTeaching'
const props=defineProps({api:Function,teacher:Boolean})
const {busy,error,notice,request,all,run}=useTeaching(props.api)
const editingId=ref(null)
const assignments=ref([]),classes=ref([]),papers=ref([]),selected=ref(null),creating=ref(false),form=ref({title:'',classId:'',paperId:'',dueAt:'',instructions:''}),submission=ref(null),answers=ref({}),submissions=ref([]),grading=ref(null),reviewing=ref(null),confirmation=ref(''),tutorText=ref(''),tutorQuestionId=ref(''),tutorReply=ref('')
const canWrite=computed(()=>selected.value?.status==='published'&&new Date(selected.value.dueAt)>new Date()&&(!submission.value||submission.value.status==='draft'))
const load=async()=>{assignments.value=await all('/assignments');classes.value=await all('/classes');if(props.teacher)papers.value=await all('/papers')}
async function detail(id){selected.value=await request(`/assignments/${id}`);creating.value=false;confirmation.value='';reviewing.value=null;grading.value=null;tutorReply.value='';tutorText.value='';tutorQuestionId.value=selected.value.paper.items[0]?.questionId||'';if(props.teacher)submissions.value=await all(`/assignments/${id}/submissions`);else{submission.value=await request(`/assignments/${id}/submission`);answers.value=copy(submission.value?.answers||{})}}
function open(a){run(()=>detail(a.id))}
function create(){editingId.value=null;creating.value=true;selected.value=null;form.value={title:'',classId:'',paperId:'',dueAt:'',instructions:''}}
function save(){run(async()=>{const a=await request('/assignments'+(editingId.value?'/'+editingId.value:''),editingId.value?'PUT':'POST',{...form.value,dueAt:new Date(form.value.dueAt).toISOString()});await load();await detail(a.id)},'作业草稿已保存，检查后点击发布。')}
function edit(){const a=selected.value;const d=new Date(a.dueAt);const local=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);editingId.value=a.id;form.value={title:a.title,classId:a.classId,paperId:papers.value.find(p=>JSON.stringify(p.data.items)===JSON.stringify(a.paper.items))?.id||'',instructions:a.instructions,dueAt:local};creating.value=true;confirmation.value=''}
function action(name){run(async()=>{if(name==='delete'){await request(`/assignments/${selected.value.id}`,'DELETE');selected.value=null;confirmation.value='';await load()}else{await request(`/assignments/${selected.value.id}/${name}`,'POST',{});await load();await detail(selected.value.id)}},'作业状态已更新。')}
function saveAnswer(submit){run(async()=>{submission.value=await request(`/assignments/${selected.value.id}/${submit?'submit':'submission'}`,submit?'POST':'PUT',{answers:answers.value});confirmation.value=''},submit?'已正式提交，等待教师批改。':'草稿已保存。')}
function review(s){reviewing.value=s;grading.value={items:selected.value.paper.items.map(i=>({questionId:i.questionId,score:s.grading?.items.find(g=>g.questionId===i.questionId)?.score??0,feedback:s.grading?.items.find(g=>g.questionId===i.questionId)?.feedback??''})),feedback:s.grading?.feedback||''}}
function grade(){run(async()=>{await request(`/assignments/${selected.value.id}/submissions/${reviewing.value.id}/grade`,'PUT',grading.value);await detail(selected.value.id)},'评分与反馈已保存，学生现在可以查看。')}
function answerText(q,value){return Array.isArray(value)?value.map(i=>String.fromCharCode(65+i)+'. '+q.options[i]).join('；'):value||'未填写'}
function tutor(){run(async()=>{const r=await request(`/assignments/${selected.value.id}/tutor`,'POST',{questionId:tutorQuestionId.value,text:tutorText.value});tutorReply.value=r.content+(r.truncated?'\n（本次回答已达到长度上限）':'')})}
onMounted(()=>run(load))
</script>
<template><section><div class="work-heading"><div><h2>{{teacher?'作业管理':'我的作业'}}</h2><p>{{teacher?'将试卷布置给班级，查看提交并提供学习反馈。':'完成班级作业，保存思路并查看教师反馈。'}}</p></div><button v-if="teacher" class="work-primary" :disabled="busy" @click="create">布置作业</button></div><p v-if="error" class="work-error" role="alert">{{error}}</p><p v-if="notice" class="work-notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在处理，请稍候…</p><div class="work-grid"><div><div class="work-list"><button v-for="a in assignments" :key="a.id" :class="{active:selected?.id===a.id}" :disabled="busy" @click="open(a)"><strong>{{a.title}}</strong><small>{{statusLabel(a.status)}} · {{dateLabel(a.dueAt)}}</small></button></div><p v-if="!assignments.length&&!busy" class="work-muted">{{teacher?'还没有布置作业。':'暂无已发布作业。请先加入班级。'}}</p><button class="work-link work-footer" :disabled="busy" @click="run(load)">刷新作业列表</button></div><div>
<form v-if="creating" class="work-card work-form" @submit.prevent="save"><fieldset :disabled="busy"><h3>{{editingId?'编辑作业草稿':'新建作业草稿'}}</h3><p v-if="editingId" class="work-muted">保存时将使用所选试卷的当前内容，请重新确认试卷。</p><p v-if="!classes.length||!papers.length" class="work-notice">发布前需要先创建班级，并在试卷管理中保存一份试卷。</p><label>作业名称<input v-model="form.title" required maxlength="150"/></label><label>接收班级<select v-model="form.classId" required><option disabled value="">选择班级</option><option v-for="c in classes" :key="c.id" :value="c.id">{{c.title}}</option></select></label><label>使用试卷<select v-model="form.paperId" required><option disabled value="">选择试卷</option><option v-for="p in papers" :key="p.id" :value="p.id">{{p.title}} · {{p.data.totalPoints}}分</option></select></label><label>截止时间（本地时间）<input type="datetime-local" v-model="form.dueAt" required/></label><label>作业说明<textarea v-model="form.instructions" maxlength="3000"/></label><button class="work-primary">保存作业草稿</button></fieldset></form>
<template v-else-if="selected"><section class="work-card"><h3>{{selected.title}}</h3><p class="work-muted">{{classes.find(c=>c.id===selected.classId)?.title}} · 截止 {{dateLabel(selected.dueAt)}}</p><span class="work-badge">{{statusLabel(selected.status)}}</span><p class="work-stem">{{selected.instructions||'暂无补充说明。'}}</p><p>共 {{selected.paper.items.length}} 题 · {{selected.paper.totalPoints}} 分</p><div v-if="teacher" class="work-actions"><button v-if="selected.status==='draft'" class="work-button" :disabled="busy" @click="edit">编辑草稿</button><button v-if="selected.status==='draft'" class="work-danger" :disabled="busy" @click="confirmation='delete'">删除草稿</button><button v-if="selected.status==='draft'" class="work-primary" :disabled="busy" @click="confirmation='publish'">发布作业</button><button v-if="selected.status==='published'" class="work-button" :disabled="busy" @click="confirmation='close'">关闭作业</button><button v-if="!selected.answersReleased&&selected.status!=='draft'&&(selected.status==='closed'||new Date(selected.dueAt)<=new Date())" class="work-button" :disabled="busy" @click="confirmation='release-answers'">开放参考答案</button><span v-if="selected.answersReleased" class="work-small">参考答案已开放</span></div><div v-if="teacher&&confirmation" class="work-notice"><p>{{confirmation==='delete'?'确定删除这份尚未发布的作业草稿？':confirmation==='publish'?'发布后班级学生即可作答，试卷内容将固定。':confirmation==='close'?'关闭后，学生将无法继续保存或提交。':'开放后，班级学生可以查看参考答案与解析。'}}</p><div class="work-actions"><button class="work-primary" :disabled="busy" @click="action(confirmation)">确认{{confirmation==='delete'?'删除':confirmation==='publish'?'发布':confirmation==='close'?'关闭':'开放'}}</button><button class="work-button" :disabled="busy" @click="confirmation=''">取消</button></div></div></section>
<template v-if="teacher"><section class="work-card"><h3>试卷内容</h3><details v-for="(i,index) in selected.paper.items" :key="i.questionId"><summary>{{index+1}}. {{i.question.stem.slice(0,50)}} · {{i.points}} 分</summary><p class="work-stem">{{i.question.stem}}</p><p v-for="(option,n) in i.question.options" :key="n">{{String.fromCharCode(65+n)}}. {{option}}</p><div class="work-result">参考答案：{{answerText(i.question,i.question.answer)}}<p>{{i.question.analysis}}</p></div></details></section><section class="work-card"><div class="work-heading"><h3>学生提交（{{submissions.length}}）</h3><button class="work-button" :disabled="busy" @click="run(()=>detail(selected.id))">刷新提交</button></div><p v-if="!submissions.length" class="work-muted">暂无正式提交，学生草稿不会在这里展示。</p><div class="work-list"><button v-for="s in submissions" :key="s.id" :disabled="busy" @click="review(s)"><strong>{{s.displayName}} · {{statusLabel(s.status)}}</strong><small>{{dateLabel(s.submittedAt)}}{{s.grading?' · '+s.grading.totalScore+' 分':''}}</small></button></div></section><form v-if="reviewing" class="work-card work-form" @submit.prevent="grade"><fieldset :disabled="busy"><h3>批改：{{reviewing.displayName}}</h3><article v-for="(i,index) in selected.paper.items" :key="i.questionId" class="work-question"><h4>{{index+1}}. {{i.question.stem}}</h4><div class="work-result">学生作答：{{answerText(i.question,reviewing.answers[i.questionId])}}</div><label>得分（满分 {{i.points}}）<input v-model.number="grading.items[index].score" type="number" min="0" :max="i.points" step="0.5" required/></label><label>逐题反馈<textarea v-model="grading.items[index].feedback" maxlength="2000"/></label></article><label>总体反馈<textarea v-model="grading.feedback" maxlength="3000"/></label><button class="work-primary">保存评分与反馈</button></fieldset></form></template>
<template v-else><form class="work-card work-form" @submit.prevent="confirmation='submit'"><p v-if="submission" class="work-notice">作答状态：{{statusLabel(submission.status)}}{{submission.grading?' · 得分 '+submission.grading.totalScore+' / '+selected.paper.totalPoints:''}}</p><p v-if="!canWrite" class="work-muted">已提交、关闭或截止的作业不能继续修改。</p><article v-for="(i,index) in selected.paper.items" :key="i.questionId" class="work-question"><h4>{{index+1}}. {{i.question.stem}} <span class="work-small">{{i.points}} 分</span></h4><AnswerInput :question="i.question" v-model="answers[i.questionId]" :name="i.questionId" :disabled="busy||!canWrite"/><div v-if="selected.answersReleased" class="work-result">参考答案：{{answerText(i.question,i.question.answer)}}<p>{{i.question.analysis}}</p></div><div v-if="submission?.grading" class="work-result">得分：{{submission.grading.items.find(g=>g.questionId===i.questionId)?.score}}<p>{{submission.grading.items.find(g=>g.questionId===i.questionId)?.feedback}}</p></div></article><p v-if="submission?.grading" class="work-result">教师反馈：{{submission.grading.feedback||'暂无补充反馈'}}</p><div v-if="canWrite" class="work-actions"><button type="button" class="work-button" :disabled="busy" @click="saveAnswer(false)">保存草稿</button><button class="work-primary" :disabled="busy">正式提交</button></div><div v-if="confirmation==='submit'" class="work-notice">提交后不能修改，请确认已完成所有题目。<div class="work-actions work-footer"><button type="button" class="work-primary" :disabled="busy" @click="saveAnswer(true)">确认提交</button><button type="button" class="work-button" :disabled="busy" @click="confirmation=''">继续检查</button></div></div></form><form class="work-card work-form" @submit.prevent="tutor"><h3>向学习助教请教</h3><p class="work-muted">描述你的思路，获取概念解释和分步提示。</p><label>辅导题目<select v-model="tutorQuestionId"><option v-for="(i,index) in selected.paper.items" :key="i.questionId" :value="i.questionId">第 {{index+1}} 题</option></select></label><label>你的问题<textarea v-model="tutorText" required maxlength="2000"/></label><button class="work-primary" :disabled="busy">获取学习提示</button><div v-if="tutorReply" class="work-result">{{tutorReply}}</div></form></template></template><div v-else class="work-empty">{{teacher?'选择一项作业查看内容与提交，或布置新的作业。':'选择一项作业，查看要求并开始作答。'}}</div></div></div></section></template>
